import unittest
from candidate import decimal_to_binary

class TestDecimalToBinaryConversion(unittest.TestCase):
    def test_decimal_to_binary_normal_case_fifteen(self):
        self.assertEqual(decimal_to_binary(15), "db1111db")

    def test_decimal_to_binary_normal_case_thirtytwo(self):
        self.assertEqual(decimal_to_binary(32), "db100000db")

    def test_decimal_to_binary_boundary_zero(self):
        self.assertEqual(decimal_to_binary(0), "db0db")

    def test_decimal_to_binary_type_error_none(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(None)

    def test_decimal_to_binary_type_error_string(self):
        with self.assertRaises(TypeError):
            decimal_to_binary("10")

    def test_decimal_to_binary_type_error_float(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(3.5)
